import json
def transform(g):
    H,W=len(g),len(g[0])
    rays={1:[(-1,-1)],3:[(-1,1)],6:[(1,-1)],8:[(1,1)],2:[(-1,1)],9:[(1,-1),(1,1)],5:[]}
    out=[r[:] for r in g]
    for r in range(H):
        for c in range(W):
            for dr,dc in rays.get(g[r][c],[]):
                rr,cc=r+dr,c+dc
                while 0<=rr<H and 0<=cc<W:
                    out[rr][cc]=g[r][c]; rr+=dr; cc+=dc
    return out
